	Namespaces map[string]string `xml:"-"`
}

// WSDLImport represents a WSDL import
type WSDLImport struct {
	Namespace string `xml:"namespace,attr"`
	Location  string `xml:"location,attr"`
}

// WSDLTypes contains schema types
type WSDLTypes struct {
	Schemas []XSDSchema `xml:"schema"`
}

// WSDLMessage represents a WSDL message
type WSDLMessage struct {
	Name  string        `xml:"name,attr"`
	Parts []MessagePart `xml:"part"`
}

// MessagePart is a part of a WSDL message
type MessagePart struct {
	Name    string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type    string `xml:"type,attr"`
}

// PortType represents a WSDL port type
type PortType struct {
	Name       string      `xml:"name,attr"`
	Operations []Operation `xml:"operation"`
}

// Operation represents a WSDL operation
type Operation struct {
	Name          string              `xml:"name,attr"`
	Documentation string              `xml:"documentation"`
	Input         *OperationMessage   `xml:"input"`
	Output        *OperationMessage   `xml:"output"`
	Fault         []OperationFault    `xml:"fault"`
}

// OperationMessage is an operation's input/output
type OperationMessage struct {
	Message string `xml:"message,attr"`
	Name    string `xml:"name,attr"`
}

// OperationFault is an operation's fault
type OperationFault struct {
	Name    string `xml:"name,attr"`
	Message string `xml:"message,attr"`
}

// Binding represents a WSDL binding
type Binding struct {
	Name       string             `xml:"name,attr"`
	Type       string             `xml:"type,attr"`
	Operations []BindingOperation `xml:"operation"`
	SOAPBinding *SOAPBinding      `xml:"http://schemas.xmlsoap.org/wsdl/soap/ binding"`
}

// SOAPBinding is SOAP binding info
type SOAPBinding struct {
	Style     string `xml:"style,attr"`
	Transport string `xml:"transport,attr"`
}

// BindingOperation is an operation in a binding
type BindingOperation struct {
	Name     string          `xml:"name,attr"`
