	Default    string          `xml:"default,attr"`
	Form       string          `xml:"form,attr"`
	SimpleType *XSDSimpleType  `xml:"simpleType"`
	Annotation *XSDAnnotation  `xml:"annotation"`
}

// XSDAnyAttribute represents xs:anyAttribute
type XSDAnyAttribute struct {
	Namespace string `xml:"namespace,attr"`
}

// XSDComplexContent represents an xs:complexContent
type XSDComplexContent struct {
	Extension   *XSDExtension   `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

// XSDSimpleContent represents an xs:simpleContent
type XSDSimpleContent struct {
	Extension   *XSDExtension   `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

// XSDExtension represents an xs:extension
type XSDExtension struct {
	Base        string         `xml:"base,attr"`
	Sequence    *XSDSequence   `xml:"sequence"`
	All         *XSDSequence   `xml:"all"`
	Choice      *XSDSequence   `xml:"choice"`
	Attributes  []XSDAttribute `xml:"attribute"`
	AnyAttribute *XSDAnyAttribute `xml:"anyAttribute"`
}

// XSDRestriction represents an xs:restriction
type XSDRestriction struct {
	Base         string               `xml:"base,attr"`
	Enumerations []XSDEnumeration     `xml:"enumeration"`
	Pattern      *XSDStringFacet      `xml:"pattern"`
	MinLength    *XSDIntFacet         `xml:"minLength"`
	MaxLength    *XSDIntFacet         `xml:"maxLength"`
	MinInclusive *XSDStringFacet      `xml:"minInclusive"`
	MaxInclusive *XSDStringFacet      `xml:"maxInclusive"`
	Sequence     *XSDSequence         `xml:"sequence"`
	All          *XSDSequence         `xml:"all"`
	Choice       *XSDSequence         `xml:"choice"`
	Attributes   []XSDAttribute       `xml:"attribute"`
	SimpleContent *XSDSimpleContent   `xml:"simpleContent"`
}

// XSDEnumeration is an XSD enum value
type XSDEnumeration struct {
	Value      string         `xml:"value,attr"`
	Annotation *XSDAnnotation `xml:"annotation"`
}

// XSDStringFacet is a string-valued facet
type XSDStringFacet struct {
	Value string `xml:"value,attr"`
}

// XSDIntFacet is an int-valued facet
type XSDIntFacet struct {
	Value int `xml:"value,attr"`
}
GOEOF
