// Package main provides the gowsdl tool for generating Go code from WSDL files.
package main

import (
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// Version of gowsdl
const Version = "v0.5.0"

// GoWSDL is the main structure for WSDL to Go code generation
type GoWSDL struct {
	file            string
	pkg             string
	outputFile      string
	dir             string
	skipTLS         bool
	makePublic      bool
	wsdl            *WSDLDefinitions
	resolvedXSDExternals map[string]bool
}

// NewGoWSDL creates a new GoWSDL instance
func NewGoWSDL(file, pkg, outputFile, dir string, skipTLS, makePublic bool) (*GoWSDL, error) {
	g := &GoWSDL{
		file:       file,
		pkg:        pkg,
		outputFile: outputFile,
		dir:        dir,
		skipTLS:    skipTLS,
		makePublic: makePublic,
		resolvedXSDExternals: make(map[string]bool),
	}
	return g, nil
}

// Start starts the code generation
func (g *GoWSDL) Start() (map[string][]byte, error) {
	err := g.loadWSDL()
	if err != nil {
		return nil, err
	}

	clientCode, err := g.generateClientCode()
	if err != nil {
		return nil, fmt.Errorf("generating client code: %v", err)
	}

	serverCode, err := g.generateServerCode()
	if err != nil {
		return nil, fmt.Errorf("generating server code: %v", err)
	}

	return map[string][]byte{
		"client": clientCode,
		"server": serverCode,
	}, nil
}

// loadWSDL loads and parses the WSDL file
func (g *GoWSDL) loadWSDL() error {
	var reader io.Reader

	if strings.HasPrefix(g.file, "http://") || strings.HasPrefix(g.file, "https://") {
		// HTTP/HTTPS file
		fmt.Fprintf(os.Stderr, "🍀  Downloading %s\n", g.file)
		resp, err := http.Get(g.file)
		if err != nil {
			return err
		}
		defer resp.Body.Close()
		reader = resp.Body
	} else {
		// Local file
		absPath, err := filepath.Abs(g.file)
		if err != nil {
			return err
		}
		fmt.Fprintf(os.Stderr, "🍀  Reading file %s\n", absPath)
		f, err := os.Open(absPath)
		if err != nil {
			return err
		}
		defer f.Close()
		reader = f
	}

	// Read the raw content for embedding in server file
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}

	g.wsdl = &WSDLDefinitions{}
	if err := xml.Unmarshal(data, g.wsdl); err != nil {
		return err
	}
	g.wsdl.rawContent = string(data)

	// Resolve external XSD schemas
	if err := g.resolveExternalSchemas(); err != nil {
		return err
	}

	return nil
}

// resolveExternalSchemas downloads/reads external XSD schemas
func (g *GoWSDL) resolveExternalSchemas() error {
	for _, schema := range g.wsdl.Types.Schemas {
		for _, imp := range schema.Imports {
			if imp.SchemaLocation == "" {
				continue
			}
			if err := g.resolveExternalSchema(imp.SchemaLocation); err != nil {
				return err
			}
		}
		for _, inc := range schema.Includes {
			if inc.SchemaLocation == "" {
				continue
			}
			if err := g.resolveExternalSchema(inc.SchemaLocation); err != nil {
				return err
			}
		}
	}
	return nil
}

// resolveExternalSchema loads an external XSD file
func (g *GoWSDL) resolveExternalSchema(location string) error {
	if g.resolvedXSDExternals[location] {
		return nil
	}
	g.resolvedXSDExternals[location] = true

	var reader io.Reader
	var data []byte
	var err error

	if strings.HasPrefix(location, "http://") || strings.HasPrefix(location, "https://") {
		fmt.Fprintf(os.Stderr, "🍀  Downloading file %s\n", location)
		resp, err := http.Get(location)
		if err != nil {
			return err
		}
		defer resp.Body.Close()
		data, err = io.ReadAll(resp.Body)
		if err != nil {
			return err
		}
	} else {
		// Local file - relative to the WSDL file
		var schemaPath string
		if filepath.IsAbs(location) {
			schemaPath = location
		} else {
			wsdlDir := filepath.Dir(g.file)
			absWSDLDir, err := filepath.Abs(wsdlDir)
			if err != nil {
				return err
			}
			schemaPath = filepath.Join(absWSDLDir, location)
		}
		fmt.Fprintf(os.Stderr, "🍀  Reading file %s\n", schemaPath)
		f, err := os.Open(schemaPath)
		if err != nil {
			return err
		}
		defer f.Close()
		reader = f
		data, err = io.ReadAll(reader)
		if err != nil {
			return err
		}
	}

	schema := &XSDSchema{}
	if err = xml.Unmarshal(data, schema); err != nil {
		return err
	}

	// Merge schema into WSDL types
	g.wsdl.Types.Schemas = append(g.wsdl.Types.Schemas, *schema)

	// Recursively resolve imports
	for _, imp := range schema.Imports {
		if imp.SchemaLocation == "" {
			continue
		}
		if err := g.resolveExternalSchema(imp.SchemaLocation); err != nil {
			return err
		}
	}

	return nil
}
