package main

import (
	"regexp"
	"strings"
	"unicode"
)

// Go keywords that require _ suffix
var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true,
	"default": true, "defer": true, "else": true, "fallthrough": true, "for": true,
	"func": true, "go": true, "goto": true, "if": true, "import": true,
	"interface": true, "map": true, "package": true, "range": true, "return": true,
	"select": true, "struct": true, "switch": true, "type": true, "var": true,
}

// Names that when used as identifiers should stay lowercase (not exported)
// These are the Go primitive type names that gowsdl keeps lowercase when they
// appear as XML element names
var goTypeNamesKeepLower = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint16": true, "uint32": true,
	"float32": true, "float64": true,
	"bool": true, "byte": true,
}

// makePublicIdentifier converts an XML name to a public Go identifier
// It capitalizes the first character of each space-separated word,
// replaces dots and dashes with underscores, and handles Go keywords/reserved names
func makePublicIdentifier(s string) string {
	if s == "" {
		return s
	}

	// Handle special chars: replace dots with underscores
	s = strings.ReplaceAll(s, ".", "_")

	// Split by spaces and capitalize each word
	parts := strings.Fields(s)
	var result string
	if len(parts) > 1 {
		var sb strings.Builder
		for _, p := range parts {
			sb.WriteString(capitalizeFirst(p))
		}
		result = sb.String()
	} else if len(parts) == 1 {
		result = capitalizeFirst(parts[0])
	} else {
		return s
	}

	// Replace dashes with underscores
	result = strings.ReplaceAll(result, "-", "_")

	return result
}

// capitalizeFirst capitalizes the first character of a string
func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	runes := []rune(s)
	runes[0] = unicode.ToUpper(runes[0])
	return string(runes)
}

// makeFieldName converts an XML element/attribute name to a Go struct field name
// Following gowsdl naming rules
func makeFieldName(name string, makePublic bool) string {
	if name == "" {
		return name
	}

	// Replace dots with underscores
	clean := strings.ReplaceAll(name, ".", "_")

	// Split by spaces, capitalize each word, join
	parts := strings.Fields(clean)
	var result string
	if len(parts) > 1 {
		var sb strings.Builder
		for _, p := range parts {
			sb.WriteString(capitalizeFirst(p))
		}
		result = sb.String()
	} else if len(parts) == 1 {
		result = capitalizeFirst(parts[0])
	} else {
		result = clean
	}

	// Replace dashes with underscores
	result = strings.ReplaceAll(result, "-", "_")

	// Check if original name (before modification) is a Go keyword
	lower := strings.ToLower(name)
	_ = lower
	if goKeywords[name] {
		return capitalizeFirst(name) + "_"
	}

	// Check if this is in the "keep lowercase" list
	if goTypeNamesKeepLower[name] {
		return name // keep lowercase
	}

	// Handle "string" specially - prepend 'A'
	if name == "string" {
		return "A" + capitalizeFirst(name)
	}

	if !makePublic {
		// lowercase first char
		runes := []rune(result)
		runes[0] = unicode.ToLower(runes[0])
		return string(runes)
	}

	return result
}

// makeTypeName converts an XML type/element name to a Go type name
func makeTypeName(name string, makePublic bool) string {
	if name == "" {
		return name
	}

	// Replace dots with underscores
	clean := strings.ReplaceAll(name, ".", "_")

	// Split by spaces, capitalize each word
	parts := strings.Fields(clean)
	var result string
	if len(parts) > 1 {
		var sb strings.Builder
		for _, p := range parts {
			sb.WriteString(capitalizeFirst(p))
		}
		result = sb.String()
	} else if len(parts) == 1 {
		result = capitalizeFirst(parts[0])
	} else {
		result = capitalizeFirst(clean)
	}

	// Replace dashes with underscores
	result = strings.ReplaceAll(result, "-", "_")

	if !makePublic {
		runes := []rune(result)
		runes[0] = unicode.ToLower(runes[0])
		return string(runes)
	}

	return result
}

// makeEnumConstName creates the Go constant name for an enum value
func makeEnumConstName(typeName, value string, makePublic bool) string {
	if value == "" {
		if makePublic {
			return typeName + "EmptyString"
		}
		return typeName // just the type name when make-public=false
	}

	// Process the value into a valid identifier
	// Replace dots with underscores
	val := strings.ReplaceAll(value, ".", "_")

	// Split by spaces and capitalize each word
	parts := strings.Fields(val)
	var valPart string
	if len(parts) > 1 {
		var sb strings.Builder
		for _, p := range parts {
			sb.WriteString(capitalizeFirst(p))
		}
		valPart = sb.String()
	} else if len(parts) == 1 {
		valPart = capitalizeFirst(parts[0])
	} else {
		valPart = capitalizeFirst(val)
	}

	// Replace dashes with underscores
	valPart = strings.ReplaceAll(valPart, "-", "_")

	if makePublic {
		return typeName + valPart
	}
	return typeName + strings.ToLower(valPart[:1]) + valPart[1:]
}

// makeOperationName converts an operation name to a Go method name
func makeOperationName(name string, makePublic bool) string {
	if name == "" {
		return name
	}

	result := makePublicIdentifier(name)
	result = strings.ReplaceAll(result, "-", "_")

	if !makePublic {
