	"long":               "int64",
	"short":              "int16",
	"byte":               "int8",
	"unsignedLong":       "uint64",
	"unsignedInt":        "uint32",
	"unsignedShort":      "uint16",
	"unsignedByte":       "byte",
	"float":              "float32",
	"double":             "float64",
	"decimal":            "float64",
	"boolean":            "bool",
	"base64Binary":       "[]byte",
	"dateTime":           "soap.XSDDateTime",
	"date":               "soap.XSDDate",
	"time":               "soap.XSDTime",
	"anyType":            "AnyType",
}

// xsdToGoTypeFull maps XSD type names (with namespace) to Go types
var xsdToGoTypeFull = map[string]string{}

// init builds full namespace map
func init() {
	// Build from xsdToGoType using common prefixes
	for k, v := range xsdToGoType {
		xsdToGoTypeFull["xsd:"+k] = v
		xsdToGoTypeFull["xs:"+k] = v
		xsdToGoTypeFull["s:"+k] = v
	}
}

// getGoType converts an XSD type reference to a Go type string
// ns is the map of namespace prefixes to namespace URIs
// targetNS is the target namespace of the current schema
func getGoType(xsdType string, ns map[string]string, targetNS string) string {
	if xsdType == "" {
		return "string"
	}

	// Check if it has a namespace prefix
	parts := strings.SplitN(xsdType, ":", 2)
	if len(parts) == 2 {
		prefix := parts[0]
		local := parts[1]

		// Check if it's an XSD namespace
		nsURI := ns[prefix]
		if nsURI == "http://www.w3.org/2001/XMLSchema" ||
			nsURI == "http://www.w3.org/1999/XMLSchema" {
			if goType, ok := xsdToGoType[local]; ok {
				return goType
			}
			return "string"
		}

		// It's a custom type from the WSDL/schema
		return makePublicIdentifier(local)
	}

	// No prefix - could be an XSD built-in or custom type
	if goType, ok := xsdToGoType[xsdType]; ok {
		return goType
	}

	// Treat as a custom type
	return makePublicIdentifier(xsdType)
}

// isXSDBuiltinType returns true if the type is an XSD built-in
func isXSDBuiltinType(typeName string) bool {
	parts := strings.SplitN(typeName, ":", 2)
	local := typeName
	if len(parts) == 2 {
		local = parts[1]
	}
	_, ok := xsdToGoType[local]
	return ok
}

// isXSDDateTimeType returns true if the type maps to a date/time soap type
func isXSDDateTimeType(goType string) bool {
	return goType == "soap.XSDDateTime" || goType == "soap.XSDDate" || goType == "soap.XSDTime"
}
