package main

import (
	"strings"
)

// xsdToGoType maps XSD type local names to Go types
// Types NOT in this map get capitalized and wrapped in pointer
var xsdToGoType = map[string]string{
	"string":             "string",
	"token":              "string",
	"boolean":            "bool",
	"int":                "int32",
	"integer":            "int32",
	"nonNegativeInteger": "uint32",
	"long":               "int64",
	"short":              "int16",
	"byte":               "int8",
	"unsignedLong":       "uint64",
	"unsignedInt":        "uint32",
	"unsignedShort":      "uint16",
	"unsignedByte":       "byte",
	"float":              "float32",
	"double":             "float64",
	"decimal":            "float64",
	"base64Binary":       "[]byte",
	"hexBinary":          "[]byte",
	"dateTime":           "soap.XSDDateTime",
	"date":               "soap.XSDDate",
	"time":               "soap.XSDTime",
	"anyType":            "AnyType",
	"anyURI":             "AnyURI",
	"NCName":             "NCName",
}

// xsdDateTimeTypes maps the soap date/time types
var xsdDateTimeTypes = map[string]bool{
	"soap.XSDDateTime": true,
	"soap.XSDDate":     true,
	"soap.XSDTime":     true,
}

// xsdValueTypes are types that don't use pointer when used as fields
var xsdValueTypes = map[string]bool{
	"string":  true,
	"bool":    true,
	"int8":    true,
	"int16":   true,
	"int32":   true,
	"int64":   true,
	"uint16":  true,
	"uint32":  true,
	"uint64":  true,
	"byte":    true,
	"float32": true,
	"float64": true,
	"[]byte":  true,
}

// isValueType returns true if the Go type is a value type (not needing pointer)
func isValueType(goType string) bool {
	if xsdValueTypes[goType] {
		return true
	}
	// Check special pre-defined types
	if goType == "AnyURI" || goType == "NCName" || goType == "AnyType" {
		return true
	}
	return false
}

// isDateTimeType returns true if the type is a soap date/time type
func isDateTimeType(goType string) bool {
	return xsdDateTimeTypes[goType]
}

// getLocalName returns the local name from a qualified name (prefix:local)
func getLocalName(qualName string) string {
	parts := strings.SplitN(qualName, ":", 2)
	if len(parts) == 2 {
		return parts[1]
	}
	return qualName
}

// getPrefix returns the namespace prefix from a qualified name
func getPrefix(qualName string) string {
	parts := strings.SplitN(qualName, ":", 2)
	if len(parts) == 2 {
		return parts[0]
	}
	return ""
}

// resolveXSDType resolves an XSD type reference to a Go type
// nsMap maps namespace prefixes to namespace URIs
// targetNS is the target namespace
func resolveXSDType(xsdType string, nsMap map[string]string) string {
	if xsdType == "" {
		return "string"
	}

	prefix := getPrefix(xsdType)
	local := getLocalName(xsdType)

	// Check if it's an XSD namespace
	if prefix != "" {
		nsURI := nsMap[prefix]
		if isXSDNamespace(nsURI) {
			if goType, ok := xsdToGoType[local]; ok {
				return goType
			}
			// Unknown XSD type - treat as custom
			return "*" + makePublicIdentifier(local)
		}
		// It's a custom namespace type
		return makePublicIdentifier(local)
	}

	// No prefix - check if it's a built-in XSD type
	if goType, ok := xsdToGoType[local]; ok {
		return goType
	}

	// Custom type
	return makePublicIdentifier(local)
}

// isXSDNamespace returns true if the namespace URI is an XSD namespace
func isXSDNamespace(nsURI string) bool {
	return nsURI == "http://www.w3.org/2001/XMLSchema" ||
		nsURI == "http://www.w3.org/1999/XMLSchema" ||
		nsURI == "http://schemas.xmlsoap.org/soap/encoding/"
}

// getFieldGoType returns the Go type for a field given xsd type, nillable, maxOccurs
func getFieldGoType(goType string, nillable bool, maxOccurs string) string {
	isSlice := maxOccurs == "unbounded" || maxOccurs == "-1"

	if goType == "" {
		goType = "string"
	}

	if isSlice {
		if isValueType(goType) {
			if nillable {
				return "[]*" + goType
			}
			return "[]" + goType
		}
		if isDateTimeType(goType) {
			if nillable {
				return "[]*" + goType
			}
			return "[]" + goType
		}
		// Custom type - always use pointer in slice
		return "[]*" + goType
	}

	// Single occurrence
	if isValueType(goType) {
		if nillable {
			return "*" + goType
		}
		return goType
	}
	if isDateTimeType(goType) {
		if nillable {
			return "*" + goType
		}
		return goType
	}
	// Custom type - always pointer
	return "*" + goType
