package main

import (
	"fmt"
	"os"
	"strings"
)

// schemaContext holds context for a specific schema
type schemaContext struct {
	targetNS  string
	qualified bool   // elementFormDefault=qualified
	attrQual  bool   // attributeFormDefault=qualified
	nsMap     map[string]string
}

// generatorContext holds the full context for code generation
type generatorContext struct {
	wsdl       *WSDLDefinitions
	makePublic bool
	nsMap      map[string]string

	// Map from type local name -> xmlName tag value (ns + " " + elementName)
	typeXMLName map[string]string
	// Map from local type name -> schema targetNS
	typeTargetNS map[string]string
}

// newGeneratorContext creates a new generator context
func newGeneratorContext(wsdl *WSDLDefinitions, makePublic bool, nsMap map[string]string) *generatorContext {
	ctx := &generatorContext{
		wsdl:         wsdl,
		makePublic:   makePublic,
		nsMap:        nsMap,
		typeXMLName:  make(map[string]string),
		typeTargetNS: make(map[string]string),
	}
	ctx.buildTypeInfo()
	return ctx
}

// buildTypeInfo builds the type information maps
func (ctx *generatorContext) buildTypeInfo() {
	// First pass: register types and their namespaces
	for _, schema := range ctx.wsdl.Types.Schemas {
		for _, ct := range schema.ComplexTypes {
			if ct.Name != "" {
				ctx.typeTargetNS[ct.Name] = schema.TargetNamespace
			}
		}
		for _, st := range schema.SimpleTypes {
			if st.Name != "" {
				ctx.typeTargetNS[st.Name] = schema.TargetNamespace
			}
		}
	}

	// Second pass: find XMLName assignments
	// Track: typeName -> set of element names that use this type  
	typeElementNames := make(map[string]map[string]bool)

	for _, schema := range ctx.wsdl.Types.Schemas {
		// Process top-level element declarations
		for _, el := range schema.Elements {
			if el.Type != "" {
				localType := getLocalName(el.Type)
				if el.Name != localType {
					if typeElementNames[localType] == nil {
						typeElementNames[localType] = make(map[string]bool)
					}
					typeElementNames[localType][el.Name] = true
				}
			}
		}

		// Process elements within complex types
		for _, ct := range schema.ComplexTypes {
			ctx.collectElementUsageFromCT(ct, typeElementNames)
		}
		for _, el := range schema.Elements {
			if el.ComplexType != nil {
				ctx.collectElementUsageFromCT(el.ComplexType, typeElementNames)
			}
		}
	}

	// Determine XMLName for types
	for typeName, elNames := range typeElementNames {
		if len(elNames) == 1 {
			for elName := range elNames {
				targetNS := ctx.typeTargetNS[typeName]
				if targetNS != "" {
					ctx.typeXMLName[typeName] = targetNS + " " + elName
				} else {
					ctx.typeXMLName[typeName] = elName
				}
			}
		}
	}
}

// collectElementUsageFromCT collects element->type usages from a complex type
func (ctx *generatorContext) collectElementUsageFromCT(ct *XSDComplexType, usage map[string]map[string]bool) {
	if ct == nil {
		return
	}
	ctx.collectFromSeq(ct.Sequence, usage)
	ctx.collectFromSeq(ct.All, usage)
	ctx.collectFromSeq(ct.Choice, usage)
	if ct.ComplexContent != nil {
		if ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			ctx.collectFromSeq(ext.Sequence, usage)
			ctx.collectFromSeq(ext.All, usage)
			ctx.collectFromSeq(ext.Choice, usage)
		}
	}
}

// collectFromSeq collects element->type usages from a sequence
func (ctx *generatorContext) collectFromSeq(seq *XSDSequence, usage map[string]map[string]bool) {
	if seq == nil {
		return
	}
	for _, el := range seq.Elements {
		if el.Type != "" && el.Name != "" {
			localType := getLocalName(el.Type)
			if el.Name != localType {
				if usage[localType] == nil {
					usage[localType] = make(map[string]bool)
				}
				usage[localType][el.Name] = true
			}
		}
		if el.ComplexType != nil {
			ctx.collectElementUsageFromCT(el.ComplexType, usage)
		}
	}
	for _, ch := range seq.Choices {
		ctx.collectFromSeq(ch, usage)
	}
	for _, s2 := range seq.Sequences {
		ctx.collectFromSeq(s2, usage)
	}
}

// warn prints a warning to stderr
func warn(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "🍀  [WARN] "+format+"\n", args...)
}

// generateClientCode generates the Go client code
func (g *GoWSDL) generateClientCode() ([]byte, error) {
	nsMap := g.buildNSMap()
	ctx := newGeneratorContext(g.wsdl, g.makePublic, nsMap)

	var sb strings.Builder

	// Header
	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString(fmt.Sprintf("package %s\n\n", g.pkg))
	sb.WriteString("import (\n")
	sb.WriteString("\t\"context\"\n")
	sb.WriteString("\t\"encoding/xml\"\n")
	sb.WriteString("\t\"github.com/hooklift/gowsdl/soap\"\n")
	sb.WriteString("\t\"time\"\n")
	sb.WriteString(")\n\n")
	sb.WriteString("// against \"unused imports\"\n")
	sb.WriteString("var _ time.Time\n")
	sb.WriteString("var _ xml.Name\n\n")

	// Always-present types
	sb.WriteString("type AnyType struct {\n\tInnerXML string `xml:\",innerxml\"`\n}\n\n")
	sb.WriteString("type AnyURI string\n\n")
	sb.WriteString("type NCName string\n\n")

	// Generate types from schemas
	for _, schema := range g.wsdl.Types.Schemas {
		sc := &schemaContext{
			targetNS:  schema.TargetNamespace,
			qualified: schema.ElementFormDefault == "qualified",
			attrQual:  schema.AttributeFormDefault == "qualified",
			nsMap:     nsMap,
		}

		// 1. Named simpleTypes first
		for _, st := range schema.SimpleTypes {
			if st.Name != "" {
				code := g.genSimpleType(st, sc, ctx)
				sb.WriteString(code)
			}
		}

		// 2. Top-level elements
		for _, el := range schema.Elements {
			code := g.genTopLevelElement(el, sc, ctx)
			sb.WriteString(code)
		}

		// 3. Named complexTypes
		for _, ct := range schema.ComplexTypes {
			code := g.genNamedComplexType(ct, sc, ctx)
			sb.WriteString(code)
		}
	}

	// Generate port types
	sb.WriteString(g.genPortTypes(ctx))

	return []byte(sb.String()), nil
}

// genSimpleType generates code for a named simpleType
func (g *GoWSDL) genSimpleType(st *XSDSimpleType, sc *schemaContext, ctx *generatorContext) string {
	if st.Restriction == nil || len(st.Restriction.Enumerations) == 0 {
		// Not an enumeration - might be a restriction of a base type
		// For non-enum simple types, we might still need to generate something
		// but gowsdl skips most of these
		return ""
	}

	typeName := makeTypeName(st.Name, g.makePublic)

	var sb strings.Builder

	// Type-level documentation
	if st.Annotation != nil && len(st.Annotation.Documentation) > 0 {
		doc := strings.TrimSpace(st.Annotation.Documentation[0])
		if doc != "" {
			sb.WriteString(formatDocComment(doc, ""))
		}
	}

	// Determine base type for the enum
	baseGoType := "string"
	if st.Restriction.Base != "" {
		base := resolveXSDType(st.Restriction.Base, sc.nsMap)
		if isValueType(base) && base != "AnyURI" && base != "NCName" && base != "AnyType" {
			baseGoType = base
		}
	}

	sb.WriteString(fmt.Sprintf("type %s %s\n\n", typeName, baseGoType))
	sb.WriteString("const (\n")

	for _, enum := range st.Restriction.Enumerations {
		// Enum documentation
		if enum.Annotation != nil && len(enum.Annotation.Documentation) > 0 {
			doc := strings.TrimSpace(enum.Annotation.Documentation[0])
			if doc != "" {
				sb.WriteString("\n")
				sb.WriteString(formatDocComment(doc, "\t"))
			}
		} else {
			sb.WriteString("\n")
		}

		constName := makeEnumConstName(typeName, enum.Value, g.makePublic)
		sb.WriteString(fmt.Sprintf("\t%s %s = %q\n", constName, typeName, enum.Value))
	}

	sb.WriteString(")\n\n")
	return sb.String()
}

// formatDocComment formats a documentation string as a Go comment
func formatDocComment(doc, indent string) string {
	doc = strings.TrimSpace(doc)
	if doc == "" {
		return ""
	}

	lines := strings.Split(doc, "\n")
	var result []string
	multiLine := len(lines) > 1

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line != "" {
			result = append(result, indent+"// "+line)
		}
	}

	if multiLine && len(result) > 0 {
		result = append(result, indent+"//")
	}

	return strings.Join(result, "\n") + "\n"
}

// genTopLevelElement generates code for a top-level element
func (g *GoWSDL) genTopLevelElement(el *XSDElement, sc *schemaContext, ctx *generatorContext) string {
	var sb strings.Builder

	if el.ComplexType != nil {
		// Inline complexType -> generate struct
		typeName := makeTypeName(el.Name, g.makePublic)
		xmlName := sc.targetNS + " " + el.Name

		// Documentation
		if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
			doc := strings.TrimSpace(el.Annotation.Documentation[0])
			if doc != "" {
				sb.WriteString(formatDocComment(doc, ""))
			}
		}

		sb.WriteString(fmt.Sprintf("type %s struct {\n", typeName))
		sb.WriteString(fmt.Sprintf("\tXMLName xml.Name `xml:\"%s\"`\n", xmlName))
		sb.WriteString("\n")

		// Fields from inline complexType
		sb.WriteString(g.genComplexTypeFields(el.ComplexType, sc, ctx, "\t"))

		sb.WriteString("}\n\n")
		return sb.String()
	}

	if el.SimpleType != nil {
		// Element with local simpleType
		typeName := makeTypeName(el.Name, g.makePublic)

		// Documentation on element
		if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
			doc := strings.TrimSpace(el.Annotation.Documentation[0])
			if doc != "" {
				sb.WriteString(formatDocComment(doc, ""))
			}
		}

		if el.SimpleType.Restriction != nil && len(el.SimpleType.Restriction.Enumerations) > 0 {
			// Enumeration simpleType
			sb.WriteString(fmt.Sprintf("type %s string\n\n", typeName))
			sb.WriteString("const (\n")

			for _, enum := range el.SimpleType.Restriction.Enumerations {
				if enum.Annotation != nil && len(enum.Annotation.Documentation) > 0 {
					doc := strings.TrimSpace(enum.Annotation.Documentation[0])
					if doc != "" {
						sb.WriteString("\n")
						sb.WriteString(formatDocComment(doc, "\t"))
					} else {
						sb.WriteString("\n")
					}
				} else {
					sb.WriteString("\n")
				}

				constName := makeEnumConstName(typeName, enum.Value, g.makePublic)
				sb.WriteString(fmt.Sprintf("\t%s %s = %q\n", constName, typeName, enum.Value))
			}

			sb.WriteString(")\n\n")
		} else {
			// Non-enumeration simpleType - skip for now
		}
		return sb.String()
	}

	if el.Type != "" {
		// Element that references a type
		localType := getLocalName(el.Type)
		goType := resolveXSDType(el.Type, sc.nsMap)

		if isDateTimeType(goType) {
			// Generate type alias for date/time types
			typeName := makeTypeName(el.Name, g.makePublic)

			// Documentation
			if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
				doc := strings.TrimSpace(el.Annotation.Documentation[0])
				if doc != "" {
					sb.WriteString(formatDocComment(doc, ""))
				}
			}

			sb.WriteString(fmt.Sprintf("type %s %s\n\n", typeName, goType))
			sb.WriteString(fmt.Sprintf("func (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n", typeName))
			sb.WriteString(fmt.Sprintf("\treturn %s(xdt).MarshalXML(e, start)\n", goType))
			sb.WriteString("}\n\n")
			sb.WriteString(fmt.Sprintf("func (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n", typeName))
			sb.WriteString(fmt.Sprintf("\treturn (*%s)(xdt).UnmarshalXML(d, start)\n", goType))
			sb.WriteString("}\n\n")
			return sb.String()
		}

		if el.Name != localType {
			// Type alias: different element name from type name
			typeName := makeTypeName(el.Name, g.makePublic)
			resolvedType := makePublicIdentifier(localType)

			// Documentation
			if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
				doc := strings.TrimSpace(el.Annotation.Documentation[0])
				if doc != "" {
					sb.WriteString(formatDocComment(doc, ""))
				}
			}

			sb.WriteString(fmt.Sprintf("type %s %s\n\n", typeName, resolvedType))
			return sb.String()
		}

		// Element with same name as type - no additional code needed
		// The type will be generated from its complexType/simpleType definition
	}

	return sb.String()
}

// genNamedComplexType generates code for a named complexType
func (g *GoWSDL) genNamedComplexType(ct *XSDComplexType, sc *schemaContext, ctx *generatorContext) string {
	if ct.Name == "" {
		return ""
	}

	typeName := makeTypeName(ct.Name, g.makePublic)
	var sb strings.Builder

	// Documentation
	if ct.Annotation != nil && len(ct.Annotation.Documentation) > 0 {
		doc := strings.TrimSpace(ct.Annotation.Documentation[0])
		if doc != "" {
			sb.WriteString(formatDocComment(doc, ""))
		}
	}

	sb.WriteString(fmt.Sprintf("type %s struct {\n", typeName))

	// XMLName if applicable
	if xmlName, ok := ctx.typeXMLName[ct.Name]; ok {
		sb.WriteString(fmt.Sprintf("\tXMLName xml.Name `xml:\"%s\"`\n\n", xmlName))
	}

	// Fields
	sb.WriteString(g.genComplexTypeFields(ct, sc, ctx, "\t"))

	sb.WriteString("}\n\n")
	return sb.String()
}

// genComplexTypeFields generates fields for a complexType
func (g *GoWSDL) genComplexTypeFields(ct *XSDComplexType, sc *schemaContext, ctx *generatorContext, indent string) string {
	var sb strings.Builder

	if ct.ComplexContent != nil {
		if ct.ComplexContent.Extension != nil {
			// Extension: embed base type + additional fields
			ext := ct.ComplexContent.Extension
			if ext.Base != "" {
				baseName := getLocalName(ext.Base)
				baseTypeName := makeTypeName(baseName, true) // base types always public
				sb.WriteString(fmt.Sprintf("%s*%s\n\n", indent, baseTypeName))
			}
			// Additional sequence/attributes
			if ext.Sequence != nil {
				sb.WriteString(g.genSequenceFields(ext.Sequence, sc, ctx, indent))
			}
			if ext.All != nil {
				sb.WriteString(g.genSequenceFields(ext.All, sc, ctx, indent))
			}
			if ext.Choice != nil {
				sb.WriteString(g.genSequenceFields(ext.Choice, sc, ctx, indent))
			}
			for _, attr := range ext.Attributes {
				sb.WriteString(g.genAttributeField(attr, sc, ctx, indent))
			}
		} else if ct.ComplexContent.Restriction != nil {
			// Restriction of complex content - generate empty struct body
			// No fields - but might have sequence with elements
		}
	} else if ct.SimpleContent != nil {
		if ct.SimpleContent.Extension != nil {
			ext := ct.SimpleContent.Extension
			// Value field for the simple content
			sb.WriteString(fmt.Sprintf("%sValue string `xml:\",chardata\" json:\"-,\"`\n", indent))
			// Attributes
			for _, attr := range ext.Attributes {
				sb.WriteString(g.genAttributeField(attr, sc, ctx, indent))
			}
		}
	} else {
		// Regular sequence/all/choice
		if ct.Sequence != nil {
			sb.WriteString(g.genSequenceFields(ct.Sequence, sc, ctx, indent))
		}
		if ct.All != nil {
			sb.WriteString(g.genSequenceFields(ct.All, sc, ctx, indent))
		}
		if ct.Choice != nil {
			sb.WriteString(g.genSequenceFields(ct.Choice, sc, ctx, indent))
		}
		for _, attr := range ct.Attributes {
			sb.WriteString(g.genAttributeField(attr, sc, ctx, indent))
		}
	}

	return sb.String()
}

// genSequenceFields generates fields from a sequence
func (g *GoWSDL) genSequenceFields(seq *XSDSequence, sc *schemaContext, ctx *generatorContext, indent string) string {
	if seq == nil {
		return ""
	}

	var sb strings.Builder

	for _, el := range seq.Elements {
		sb.WriteString(g.genElementField(el, sc, ctx, indent))
	}

	for _, choice := range seq.Choices {
		sb.WriteString(g.genSequenceFields(choice, sc, ctx, indent))
	}

	for _, s2 := range seq.Sequences {
		sb.WriteString(g.genSequenceFields(s2, sc, ctx, indent))
	}

	return sb.String()
}

// genElementField generates a struct field for an element
func (g *GoWSDL) genElementField(el *XSDElement, sc *schemaContext, ctx *generatorContext, indent string) string {
	if el.Ref != "" {
		// Referenced element - skip for now
		return ""
	}

	if el.Name == "" {
		return ""
	}

	var sb strings.Builder

	// Documentation
	if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
		doc := strings.TrimSpace(el.Annotation.Documentation[0])
		if doc != "" {
			sb.WriteString(formatDocComment(doc, indent))
		}
	} else if el.ComplexType != nil && el.ComplexType.Annotation != nil {
		// No annotation on element, but might be on complexType
	}

	fieldName := makeFieldName(el.Name, g.makePublic)
	xmlTag := el.Name
	jsonTag := el.Name

	if el.ComplexType != nil {
		// Inline complex type -> anonymous struct field
		ct := el.ComplexType
		isSlice := el.MaxOccurs == "unbounded"

		if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
			// simpleContent extension -> anonymous struct with Value + attrs
			ext := ct.SimpleContent.Extension

			var typeStr string
			if isSlice {
				typeStr = "[]struct {"
			} else {
				typeStr = "struct {"
			}

			sb.WriteString(fmt.Sprintf("%s%s %s\n", indent, fieldName, typeStr))
			sb.WriteString(fmt.Sprintf("%s\tValue string `xml:\",chardata\" json:\"-,\"`\n", indent))
			sb.WriteString("\n")
			for _, attr := range ext.Attributes {
				sb.WriteString(g.genAttributeField(attr, sc, ctx, indent+"\t"))
			}
			sb.WriteString(fmt.Sprintf("%s} `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, xmlTag, jsonTag))
		} else if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
			// complexContent extension inline -> struct with embedded base + attrs
			ext := ct.ComplexContent.Extension
			baseName := getLocalName(ext.Base)
			baseTypeName := makeTypeName(baseName, true)

			var typeStr string
			if isSlice {
				typeStr = "[]struct {"
			} else {
				typeStr = "struct {"
			}

			sb.WriteString(fmt.Sprintf("%s%s %s\n", indent, fieldName, typeStr))
			sb.WriteString(fmt.Sprintf("%s\t*%s\n\n", indent, baseTypeName))
			for _, attr := range ext.Attributes {
				sb.WriteString(g.genAttributeField(attr, sc, ctx, indent+"\t"))
			}
			if ext.Sequence != nil {
				sb.WriteString(g.genSequenceFields(ext.Sequence, sc, ctx, indent+"\t"))
			}
			sb.WriteString(fmt.Sprintf("%s} `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, xmlTag, jsonTag))
		} else {
			// Regular inline complex type
			var typeStr string
			if isSlice {
				typeStr = "[]struct {"
			} else {
				typeStr = "struct {"
			}
			sb.WriteString(fmt.Sprintf("%s%s %s\n", indent, fieldName, typeStr))
			sb.WriteString(g.genComplexTypeFields(ct, sc, ctx, indent+"\t"))
			sb.WriteString(fmt.Sprintf("%s} `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, xmlTag, jsonTag))
		}
	} else if el.SimpleType != nil {
		// Inline simpleType - use string
		sb.WriteString(fmt.Sprintf("%s%s string `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, fieldName, xmlTag, jsonTag))
	} else if el.Type != "" {
		// Reference to a named type
		goType := resolveXSDType(el.Type, sc.nsMap)
		fieldType := getFieldGoType(goType, el.Nillable, el.MaxOccurs)
		sb.WriteString(fmt.Sprintf("%s%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, fieldName, fieldType, xmlTag, jsonTag))
	} else {
		// No type specified - use string
		sb.WriteString(fmt.Sprintf("%s%s string `xml:\"%s,omitempty\" json:\"%s,omitempty\"`\n\n", indent, fieldName, xmlTag, jsonTag))
	}

	return sb.String()
}

// genAttributeField generates a struct field for an attribute
func (g *GoWSDL) genAttributeField(attr *XSDAttribute, sc *schemaContext, ctx *generatorContext, indent string) string {
	if attr == nil {
		return ""
	}

	var name, typeName string
	var ns string

	if attr.Ref != "" {
		// Attribute reference - look up the referenced attribute
		localRef := getLocalName(attr.Ref)
		name = localRef
		// Find the referenced attribute type
		for _, schema := range g.wsdl.Types.Schemas {
			for _, a := range schema.Attributes {
				if a.Name == localRef {
					typeName = resolveXSDType(a.Type, sc.nsMap)
					ns = schema.TargetNamespace
					break
				}
			}
		}
		if typeName == "" {
			typeName = "string"
		}
		if ns == "" {
			ns = sc.targetNS
		}
	} else if attr.Name != "" {
		name = attr.Name
		if attr.Type != "" {
			typeName = resolveXSDType(attr.Type, sc.nsMap)
		} else if attr.SimpleType != nil {
			// Inline simple type - usually string
			typeName = "string"
		} else {
			typeName = "string"
		}
		ns = sc.targetNS
	} else {
		return ""
	}

	// Attributes always get the namespace in their xml tag
	fieldName := makeFieldName(name, true) // attributes always public

	// Documentation
	var sb strings.Builder
	if attr.Annotation != nil && len(attr.Annotation.Documentation) > 0 {
		doc := strings.TrimSpace(attr.Annotation.Documentation[0])
		if doc != "" {
			sb.WriteString(formatDocComment(doc, indent))
		}
	}

	var xmlTagNS string
	if ns != "" {
		xmlTagNS = ns + " "
	}

	// Get appropriate field type for attribute
	attrGoType := typeName
	if !isValueType(attrGoType) && !isDateTimeType(attrGoType) {
		// Custom type for attribute - use pointer? Actually let's check...
		// Looking at the examples, attributes use value types
		// If it's a custom type reference, it might be a pointer
		attrGoType = "*" + attrGoType
	}

	sb.WriteString(fmt.Sprintf("%s%s %s `xml:\"%s%s,attr,omitempty\" json:\"%s,omitempty\"`\n\n",
		indent, fieldName, attrGoType, xmlTagNS, name, name))

	return sb.String()
}

// getSoapAction gets the SOAP action for an operation
func (g *GoWSDL) getSoapAction(portTypeName, opName string) string {
	for _, binding := range g.wsdl.Bindings {
		bindingLocalType := getLocalName(binding.Type)
		if bindingLocalType == portTypeName {
			for _, op := range binding.Operations {
				if op.Name == opName {
					if op.SOAPOp != nil {
						return op.SOAPOp.SoapAction
					}
					if op.SOAP12Op != nil {
						return op.SOAP12Op.SoapAction
					}
				}
			}
		}
	}
	return ""
}

// getMessageType returns the Go type name for a message
func (g *GoWSDL) getMessageType(messageName string) string {
	localName := getLocalName(messageName)
	for _, msg := range g.wsdl.Messages {
		if msg.Name == localName {
			if len(msg.Parts) == 0 {
				return "EmptyString"
			}
			for _, part := range msg.Parts {
				if part.Element != "" {
					return makePublicIdentifier(getLocalName(part.Element))
				}
				if part.Type != "" {
					return makePublicIdentifier(getLocalName(part.Type))
				}
			}
		}
	}
	return "EmptyString"
}

// genPortTypes generates interface and implementation for all port types
func (g *GoWSDL) genPortTypes(ctx *generatorContext) string {
	var sb strings.Builder

	for _, pt := range g.wsdl.PortTypes {
		sb.WriteString(g.genPortType(pt, ctx))
	}

	return sb.String()
}

// genPortType generates the interface and implementation for one port type
func (g *GoWSDL) genPortType(pt *PortType, ctx *generatorContext) string {
	var sb strings.Builder

	interfaceName := makeTypeName(pt.Name, true) // interface names always public
	structName := lowercaseFirst(interfaceName)

	// Check if any operations have valid messages
	var validOps []*Operation
	for _, op := range pt.Operations {
		inputType := ""
		outputType := ""
		if op.Input != nil {
			inputType = g.getMessageType(op.Input.Message)
			if inputType == "EmptyString" {
				// Check if message exists with no parts
				localName := getLocalName(op.Input.Message)
				hasMsgDef := false
				for _, msg := range g.wsdl.Messages {
					if msg.Name == localName {
						hasMsgDef = true
						if len(msg.Parts) == 0 {
							warn("%s message doesn't have any parts, ignoring message...", msg.Name)
						}
						break
					}
				}
				if !hasMsgDef {
					warn("%s message doesn't have any parts, ignoring message...", localName)
				}
			}
		}
		if op.Output != nil {
			outputType = g.getMessageType(op.Output.Message)
			_ = outputType
		}
		_ = inputType
		validOps = append(validOps, op)
	}

	if len(validOps) == 0 {
		return ""
	}

	// Interface
	sb.WriteString(fmt.Sprintf("type %s interface {\n", interfaceName))
	for _, op := range validOps {
		opName := makeOperationName(op.Name, g.makePublic)

		inputType := "EmptyString"
		outputType := "EmptyString"
		if op.Input != nil {
			inputType = g.getMessageType(op.Input.Message)
		}
		if op.Output != nil {
			outputType = g.getMessageType(op.Output.Message)
		}

		// Documentation
		if op.Documentation != "" {
			doc := strings.TrimSpace(op.Documentation)
			if doc != "" {
				sb.WriteString(fmt.Sprintf("\n\t/* %s */\n", doc))
			}
		}

		sb.WriteString(fmt.Sprintf("\t%s(request *%s) (*%s, error)\n\n", opName, inputType, outputType))
		ctxName := opName + "Context"
		sb.WriteString(fmt.Sprintf("\t%s(ctx context.Context, request *%s) (*%s, error)\n\n", ctxName, inputType, outputType))
	}
	sb.WriteString("}\n\n")

	// Struct
	sb.WriteString(fmt.Sprintf("type %s struct {\n", structName))
	sb.WriteString("\tclient *soap.Client\n")
	sb.WriteString("}\n\n")

	// Constructor
	sb.WriteString(fmt.Sprintf("func New%s(client *soap.Client) %s {\n", interfaceName, interfaceName))
	sb.WriteString(fmt.Sprintf("\treturn &%s{\n", structName))
	sb.WriteString("\t\tclient: client,\n")
	sb.WriteString("\t}\n")
	sb.WriteString("}\n\n")

	// Methods
	for _, op := range validOps {
		opName := makeOperationName(op.Name, g.makePublic)
		ctxName := opName + "Context"

		inputType := "EmptyString"
		outputType := "EmptyString"
		if op.Input != nil {
			inputType = g.getMessageType(op.Input.Message)
		}
		if op.Output != nil {
			outputType = g.getMessageType(op.Output.Message)
		}

		soapAction := g.getSoapAction(pt.Name, op.Name)
		if soapAction == "" {
			soapAction = "''"
		}

		// Context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %s(ctx context.Context, request *%s) (*%s, error) {\n",
			structName, ctxName, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\tresponse := new(%s)\n", outputType))
		sb.WriteString(fmt.Sprintf("\terr := service.client.CallContext(ctx, %q, request, response)\n", soapAction))
		sb.WriteString("\tif err != nil {\n")
		sb.WriteString("\t\treturn nil, err\n")
		sb.WriteString("\t}\n\n")
		sb.WriteString("\treturn response, nil\n")
		sb.WriteString("}\n\n")

		// Non-context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %s(request *%s) (*%s, error) {\n",
			structName, opName, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\treturn service.%s(\n", ctxName))
		sb.WriteString("\t\tcontext.Background(),\n")
		sb.WriteString("\t\trequest,\n")
		sb.WriteString("\t)\n")
		sb.WriteString("}\n\n")
	}

	return sb.String()
}

// generateServerCode generates the server-side Go code
func (g *GoWSDL) generateServerCode() ([]byte, error) {
	var sb strings.Builder

	// Header
	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString(fmt.Sprintf("package %s\n\n", g.pkg))
	sb.WriteString("import (\n")
	sb.WriteString("\t\"encoding/xml\"\n")
	sb.WriteString("\t\"errors\"\n")
	sb.WriteString("\t\"fmt\"\n")
	sb.WriteString("\t\"net/http\"\n")
	sb.WriteString("\t\"reflect\"\n")
	sb.WriteString("\t\"strings\"\n")
	sb.WriteString(")\n\n")

	// WSDL content as raw string
	sb.WriteString("var wsdl = `")
	sb.WriteString(g.wsdl.rawContent)
	sb.WriteString("`\n\n")

	// Error variable
	sb.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	// SOAPEnvelopeRequest
	sb.WriteString("type SOAPEnvelopeRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n")
	sb.WriteString("\tBody    SOAPBodyRequest\n")
	sb.WriteString("}\n\n")

	// SOAPBodyRequest
	sb.WriteString("type SOAPBodyRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n")
	sb.WriteString("\n")

	// Collect all operations from all port types for the body
	ops := g.collectAllOperations()
	for _, op := range ops {
		sb.WriteString(fmt.Sprintf("\t%s *%s `xml:,omitempty`\n", op.fieldName, op.inputType))
		sb.WriteString("\n")
	}

	sb.WriteString("}\n\n")

	// SOAPEnvelopeResponse
	sb.WriteString("type SOAPEnvelopeResponse struct {\n")
	sb.WriteString("\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n")
	sb.WriteString("\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n")
	sb.WriteString("\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n")
	sb.WriteString("\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n")
	sb.WriteString("\tBody SOAPBodyResponse\n")
	sb.WriteString("}\n\n")

	// NewSOAPEnvelopResponse constructor
	sb.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n")
	sb.WriteString("\treturn &SOAPEnvelopeResponse{\n")
	sb.WriteString("\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n")
	sb.WriteString("\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n")
	sb.WriteString("\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n")
	sb.WriteString("\t}\n")
	sb.WriteString("}\n\n")

	// Fault
	sb.WriteString("type Fault struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n")
	sb.WriteString("\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n")
	sb.WriteString("\tCode   string `xml:\"faultcode,omitempty\"`\n")
	sb.WriteString("\tString string `xml:\"faultstring,omitempty\"`\n")
	sb.WriteString("\tActor  string `xml:\"faultactor,omitempty\"`\n")
	sb.WriteString("\tDetail string `xml:\"detail,omitempty\"`\n")
	sb.WriteString("}\n\n")

	// SOAPBodyResponse
	sb.WriteString("type SOAPBodyResponse struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"soap:Body\"`\n")
	sb.WriteString("\tFault   *Fault   `xml:\",omitempty\"`\n\n")
	for _, op := range ops {
		sb.WriteString(fmt.Sprintf("\t%s *%s `xml:\",omitempty\"`\n\n", op.fieldName, op.outputType))
	}
	sb.WriteString("}\n\n")

	// Handler functions for each operation
	for _, op := range ops {
		sb.WriteString(fmt.Sprintf("func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n",
			op.fieldName, op.inputType, op.outputType))
		sb.WriteString("\treturn nil, WSDLUndefinedError\n")
		sb.WriteString("}\n\n")
	}

	// call function
	sb.WriteString(g.genServerCallFunction())

	// Endpoint function
	sb.WriteString("func Endpoint(w http.ResponseWriter, r *http.Request) {\n")
	sb.WriteString("\trequest := SOAPEnvelopeRequest{}\n")
	sb.WriteString("\trequest.call(w, r)\n")
	sb.WriteString("}\n")

	return []byte(sb.String()), nil
}

// serverOperation represents an operation in the server
type serverOperation struct {
	fieldName  string
	inputType  string
	outputType string
}

// collectAllOperations collects all operations from all port types
func (g *GoWSDL) collectAllOperations() []serverOperation {
	var ops []serverOperation
	seen := make(map[string]bool)

	for _, pt := range g.wsdl.PortTypes {
		for _, op := range pt.Operations {
			inputType := "EmptyString"
			outputType := "EmptyString"
			if op.Input != nil {
				inputType = g.getMessageType(op.Input.Message)
			}
			if op.Output != nil {
				outputType = g.getMessageType(op.Output.Message)
			}

			// Use inputType as field name
			key := inputType + ":" + outputType
			if !seen[key] {
				seen[key] = true
				ops = append(ops, serverOperation{
					fieldName:  inputType,
					inputType:  inputType,
					outputType: outputType,
				})
			} else {
				// If same input type but different output, still add it
				ops = append(ops, serverOperation{
					fieldName:  inputType,
					inputType:  inputType,
					outputType: outputType,
				})
			}
		}
	}

	return ops
}

// genServerCallFunction generates the call function for the server
func (g *GoWSDL) genServerCallFunction() string {
	return `func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {
	w.Header().Add("Content-Type", "text/xml; charset=utf-8")
	val := reflect.ValueOf(&service.Body).Elem()
	n := val.NumField()
	var field reflect.Value
	var name string
	find := false

	if r.Method == http.MethodGet {
		w.Write([]byte(wsdl))
		return
	}

	resp := NewSOAPEnvelopResponse()
	defer func() {
		if r := recover(); r != nil {
			resp.Body.Fault = &Fault{}
			resp.Body.Fault.Space = "http://schemas.xmlsoap.org/soap/envelope/"
			resp.Body.Fault.Code = "soap:Server"
			resp.Body.Fault.Detail = fmt.Sprintf("%v", r)
			resp.Body.Fault.String = fmt.Sprintf("%v", r)
		}
		xml.NewEncoder(w).Encode(resp)
	}()

	header := r.Header.Get("Content-Type")
	if strings.Index(header, "application/soap+xml") >= 0 {
		panic("Could not find an appropriate Transport Binding to invoke.")
	}

	err := xml.NewDecoder(r.Body).Decode(service)
	if err != nil {
		panic(err)
	}

	for i := 0; i < n; i++ {
		field = val.Field(i)
		name = val.Type().Field(i).Name
		if field.Kind() != reflect.Ptr {
			continue
		}
		if field.IsNil() {
			continue
		}
		if field.IsValid() {
			find = true
			break
		}
	}

	if !find {
		panic(WSDLUndefinedError)
	} else {
		m := val.Addr().MethodByName(name + "Func")
		if !m.IsValid() {
			panic(WSDLUndefinedError)
		}

		vals := m.Call([]reflect.Value{field})
		if vals[1].IsNil() {
