func warn(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "🍀  [WARN] "+format+"\n", args...)
}

// formatDoc formats a documentation string as Go comment lines
func formatDoc(doc, indent string) string {
	doc = strings.TrimSpace(doc)
	if doc == "" {
		return ""
	}
	lines := strings.Split(doc, "\n")
	var result []string
	isMultiLine := false
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line != "" {
			result = append(result, indent+"// "+line)
			isMultiLine = len(result) > 1
		}
	}
	if isMultiLine {
		result = append(result, indent+"//")
	}
	if len(result) == 0 {
		return ""
	}
	return strings.Join(result, "\n") + "\n"
}

// generateClientCode generates the client-side code
func (g *GoWSDL) generateClientCode() ([]byte, error) {
	nsMap := g.buildNSMap()
	ctx := newGeneratorContext(g.wsdl, g.makePublic, nsMap)

	var sb strings.Builder
	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString(fmt.Sprintf("package %s\n\n", g.pkg))
	sb.WriteString("import (\n\t\"context\"\n\t\"encoding/xml\"\n\t\"github.com/hooklift/gowsdl/soap\"\n\t\"time\"\n)\n\n")
	sb.WriteString("// against \"unused imports\"\nvar _ time.Time\nvar _ xml.Name\n\n")
	sb.WriteString("type AnyType struct {\n\tInnerXML string `xml:\",innerxml\"`\n}\n\n")
	sb.WriteString("type AnyURI string\n\n")
	sb.WriteString("type NCName string\n\n")

	for _, schema := range g.wsdl.Types.Schemas {
		sc := &schemaContext{
			targetNS:  schema.TargetNamespace,
			qualified: schema.ElementFormDefault == "qualified",
			attrQual:  schema.AttributeFormDefault == "qualified",
			nsMap:     nsMap,
		}
		// 1. Named simpleTypes
		for _, st := range schema.SimpleTypes {
			if st.Name != "" {
				sb.WriteString(g.genNamedSimpleType(st, sc))
			}
		}
		// 2. Top-level elements
		for _, el := range schema.Elements {
			sb.WriteString(g.genTopLevelElement(el, sc, ctx))
		}
		// 3. Named complexTypes
		for _, ct := range schema.ComplexTypes {
			sb.WriteString(g.genNamedComplexType(ct, sc, ctx))
		}
	}

	sb.WriteString(g.genPortTypes(ctx))
	return []byte(sb.String()), nil
}

// genNamedSimpleType generates code for a named simpleType
func (g *GoWSDL) genNamedSimpleType(st *XSDSimpleType, sc *schemaContext) string {
	if st.Restriction == nil || len(st.Restriction.Enumerations) == 0 {
		return ""
	}
	typeName := makeTypeName(st.Name, g.makePublic)
	var sb strings.Builder
	if st.Annotation != nil && len(st.Annotation.Documentation) > 0 {
		sb.WriteString(formatDoc(st.Annotation.Documentation[0], ""))
	}
	sb.WriteString(fmt.Sprintf("type %s string\n\n", typeName))
	sb.WriteString("const (\n")
	for _, enum := range st.Restriction.Enumerations {
		sb.WriteString("\n")
		if enum.Annotation != nil && len(enum.Annotation.Documentation) > 0 {
			sb.WriteString(formatDoc(enum.Annotation.Documentation[0], "\t"))
		}
		constName := makeEnumConstName(typeName, enum.Value, g.makePublic)
		sb.WriteString(fmt.Sprintf("\t%s %s = %q\n", constName, typeName, enum.Value))
	}
	sb.WriteString(")\n\n")
	return sb.String()
}

// genTopLevelElement generates code for a top-level element
func (g *GoWSDL) genTopLevelElement(el *XSDElement, sc *schemaContext, ctx *generatorContext) string {
	var sb strings.Builder

	if el.ComplexType != nil {
		// Inline complexType -> struct
		typeName := makeTypeName(el.Name, g.makePublic)
		xmlName := ""
		if sc.targetNS != "" {
			xmlName = sc.targetNS + " " + el.Name
		} else {
			xmlName = el.Name
		}
		if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
			sb.WriteString(formatDoc(el.Annotation.Documentation[0], ""))
		}
		fields := g.genComplexTypeFields(el.ComplexType, sc, ctx, "\t")
		sb.WriteString(fmt.Sprintf("type %s struct {\n", typeName))
		sb.WriteString(fmt.Sprintf("\tXMLName xml.Name `xml:\"%s\"`\n", xmlName))
		if fields != "" {
			sb.WriteString("\n")
			sb.WriteString(strings.TrimRight(fields, "\n"))
			sb.WriteString("\n")
		}
		sb.WriteString("}\n\n")
		return sb.String()
	}

	if el.SimpleType != nil && el.SimpleType.Restriction != nil {
		// Element with local simpleType restriction
		typeName := makeTypeName(el.Name, g.makePublic)
		if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
			sb.WriteString(formatDoc(el.Annotation.Documentation[0], ""))
		}
		if len(el.SimpleType.Restriction.Enumerations) > 0 {
			sb.WriteString(fmt.Sprintf("type %s string\n\n", typeName))
			sb.WriteString("const (\n")
			for _, enum := range el.SimpleType.Restriction.Enumerations {
				sb.WriteString("\n")
				if enum.Annotation != nil && len(enum.Annotation.Documentation) > 0 {
					sb.WriteString(formatDoc(enum.Annotation.Documentation[0], "\t"))
				}
				constName := makeEnumConstName(typeName, enum.Value, g.makePublic)
				sb.WriteString(fmt.Sprintf("\t%s %s = %q\n", constName, typeName, enum.Value))
			}
			sb.WriteString(")\n\n")
		}
		return sb.String()
	}

	if el.Type != "" {
		localType := getLocalName(el.Type)
		goType := g.resolveType(el.Type, sc.nsMap)

		if isDateTimeType(goType) {
			typeName := makeTypeName(el.Name, g.makePublic)
			if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
				sb.WriteString(formatDoc(el.Annotation.Documentation[0], ""))
			}
			sb.WriteString(fmt.Sprintf("type %s %s\n\n", typeName, goType))
			sb.WriteString(fmt.Sprintf("func (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n", typeName))
			sb.WriteString(fmt.Sprintf("\treturn %s(xdt).MarshalXML(e, start)\n", goType))
			sb.WriteString("}\n\n")
			sb.WriteString(fmt.Sprintf("func (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n", typeName))
			sb.WriteString(fmt.Sprintf("\treturn (*%s)(xdt).UnmarshalXML(d, start)\n", goType))
			sb.WriteString("}\n\n")
			return sb.String()
		}

		if el.Name != localType {
			// Type alias
			typeName := makeTypeName(el.Name, g.makePublic)
			resolvedType := makePublicIdentifier(localType)
			if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
				sb.WriteString(formatDoc(el.Annotation.Documentation[0], ""))
			}
			sb.WriteString(fmt.Sprintf("type %s %s\n\n", typeName, resolvedType))
		}
	}

	return sb.String()
}

// genNamedComplexType generates code for a named complexType
func (g *GoWSDL) genNamedComplexType(ct *XSDComplexType, sc *schemaContext, ctx *generatorContext) string {
	if ct.Name == "" {
		return ""
	}
	typeName := makeTypeName(ct.Name, g.makePublic)
	var sb strings.Builder
	if ct.Annotation != nil && len(ct.Annotation.Documentation) > 0 {
		sb.WriteString(formatDoc(ct.Annotation.Documentation[0], ""))
	}
	sb.WriteString(fmt.Sprintf("type %s struct {\n", typeName))

	xmlName, hasXMLName := ctx.typeXMLName[ct.Name]
	if hasXMLName {
		sb.WriteString(fmt.Sprintf("\tXMLName xml.Name `xml:\"%s\"`\n", xmlName))
		// Will add blank line before first field in body
	}

	fields := g.genComplexTypeFields(ct, sc, ctx, "\t")
	if fields != "" {
		if hasXMLName {
			sb.WriteString("\n")
		}
		sb.WriteString(strings.TrimRight(fields, "\n"))
		sb.WriteString("\n")
	}
	sb.WriteString("}\n\n")
	return sb.String()
}

// genComplexTypeFields generates the fields of a complex type (without the type declaration wrapper)
func (g *GoWSDL) genComplexTypeFields(ct *XSDComplexType, sc *schemaContext, ctx *generatorContext, indent string) string {
	if ct == nil {
		return ""
	}

	var items []string

	if ct.ComplexContent != nil {
		if ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			if ext.Base != "" {
				baseName := getLocalName(ext.Base)
				baseTypeName := makeTypeName(baseName, true)
				items = append(items, fmt.Sprintf("%s*%s", indent, baseTypeName))
			}
			items = append(items, g.collectSeqFields(ext.Sequence, sc, ctx, indent)...)
			items = append(items, g.collectSeqFields(ext.All, sc, ctx, indent)...)
			items = append(items, g.collectSeqFields(ext.Choice, sc, ctx, indent)...)
			for _, attr := range ext.Attributes {
				item := g.genAttrField(attr, sc, ctx, indent)
				if item != "" {
					items = append(items, item)
				}
			}
		}
		// restriction: generate empty struct
	} else if ct.SimpleContent != nil {
		if ct.SimpleContent.Extension != nil {
			ext := ct.SimpleContent.Extension
			items = append(items, fmt.Sprintf("%sValue string `xml:\",chardata\" json:\"-,\"`", indent))
			for _, attr := range ext.Attributes {
				item := g.genAttrField(attr, sc, ctx, indent)
				if item != "" {
					items = append(items, item)
				}
			}
		}
	} else {
		items = append(items, g.collectSeqFields(ct.Sequence, sc, ctx, indent)...)
		items = append(items, g.collectSeqFields(ct.All, sc, ctx, indent)...)
		items = append(items, g.collectSeqFields(ct.Choice, sc, ctx, indent)...)
		for _, attr := range ct.Attributes {
			item := g.genAttrField(attr, sc, ctx, indent)
			if item != "" {
				items = append(items, item)
			}
		}
	}

	return strings.Join(items, "\n\n") + "\n"
}

// collectSeqFields collects field strings from a sequence
func (g *GoWSDL) collectSeqFields(seq *XSDSequence, sc *schemaContext, ctx *generatorContext, indent string) []string {
	if seq == nil {
		return nil
	}
	var items []string
	for _, el := range seq.Elements {
		item := g.genElField(el, sc, ctx, indent)
		if item != "" {
			items = append(items, item)
		}
	}
	for _, ch := range seq.Choices {
		items = append(items, g.collectSeqFields(ch, sc, ctx, indent)...)
	}
	for _, s2 := range seq.Sequences {
		items = append(items, g.collectSeqFields(s2, sc, ctx, indent)...)
	}
	return items
}

// genElField generates a single element field string (without trailing newline)
func (g *GoWSDL) genElField(el *XSDElement, sc *schemaContext, ctx *generatorContext, indent string) string {
	if el.Ref != "" || el.Name == "" {
		return ""
	}

	fieldName := makeFieldName(el.Name, g.makePublic)
	xmlTag := el.Name
	jsonTag := el.Name

	var doc string
	if el.Annotation != nil && len(el.Annotation.Documentation) > 0 {
		d := strings.TrimSpace(el.Annotation.Documentation[0])
		if d != "" {
			doc = formatDoc(d, indent)
		}
	}

	if el.ComplexType != nil {
		ct := el.ComplexType
		isSlice := el.MaxOccurs == "unbounded"
		var typeStr string
		if isSlice {
			typeStr = "[]struct {"
		} else {
			typeStr = "struct {"
		}

		var innerFields string
		if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
			ext := ct.SimpleContent.Extension
			var innerItems []string
			innerItems = append(innerItems, fmt.Sprintf("%s\tValue string `xml:\",chardata\" json:\"-,\"`", indent))
			for _, attr := range ext.Attributes {
				item := g.genAttrField(attr, sc, ctx, indent+"\t")
				if item != "" {
					innerItems = append(innerItems, item)
				}
			}
			innerFields = strings.Join(innerItems, "\n\n") + "\n"
		} else if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			baseName := getLocalName(ext.Base)
			baseTypeName := makeTypeName(baseName, true)
			var innerItems []string
			innerItems = append(innerItems, fmt.Sprintf("%s\t*%s", indent, baseTypeName))
			for _, attr := range ext.Attributes {
				item := g.genAttrField(attr, sc, ctx, indent+"\t")
				if item != "" {
					innerItems = append(innerItems, item)
				}
			}
			innerItems = append(innerItems, g.collectSeqFields(ext.Sequence, sc, ctx, indent+"\t")...)
			innerFields = strings.Join(innerItems, "\n\n") + "\n"
		} else {
			innerFields = g.genComplexTypeFields(ct, sc, ctx, indent+"\t")
		}

		var result strings.Builder
		if doc != "" {
			result.WriteString(doc)
		}
		result.WriteString(fmt.Sprintf("%s%s %s\n", indent, fieldName, typeStr))
		if innerFields != "" {
			result.WriteString(strings.TrimRight(innerFields, "\n"))
			result.WriteString("\n")
		}
		result.WriteString(fmt.Sprintf("%s} `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", indent, xmlTag, jsonTag))
		return result.String()
	}

	if el.SimpleType != nil {
		var result strings.Builder
		if doc != "" {
			result.WriteString(doc)
		}
		result.WriteString(fmt.Sprintf("%s%s string `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", indent, fieldName, xmlTag, jsonTag))
		return result.String()
	}

	if el.Type != "" {
		goType := g.resolveType(el.Type, sc.nsMap)
		fieldType := getFieldGoType(goType, el.Nillable, el.MaxOccurs)
		var result strings.Builder
		if doc != "" {
			result.WriteString(doc)
		}
		result.WriteString(fmt.Sprintf("%s%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", indent, fieldName, fieldType, xmlTag, jsonTag))
		return result.String()
	}

	// No type specified
	var result strings.Builder
	if doc != "" {
		result.WriteString(doc)
	}
	result.WriteString(fmt.Sprintf("%s%s string `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", indent, fieldName, xmlTag, jsonTag))
	return result.String()
}

// genAttrField generates a single attribute field string (without trailing newline)
func (g *GoWSDL) genAttrField(attr *XSDAttribute, sc *schemaContext, ctx *generatorContext, indent string) string {
	if attr == nil {
		return ""
	}

	var name, typeName, nsURI string

	if attr.Ref != "" {
		localRef := getLocalName(attr.Ref)
		name = localRef
		// Look up referenced attribute
		for _, schema := range g.wsdl.Types.Schemas {
			for _, a := range schema.Attributes {
				if a.Name == localRef {
					if a.Type != "" {
						typeName = g.resolveType(a.Type, sc.nsMap)
					} else if a.SimpleType != nil {
						typeName = "string"
					} else {
						typeName = "string"
					}
					nsURI = schema.TargetNamespace
					break
				}
			}
		}
		if typeName == "" {
			typeName = "string"
		}
		if nsURI == "" {
			nsURI = sc.targetNS
		}
	} else if attr.Name != "" {
		name = attr.Name
		if attr.Type != "" {
			typeName = g.resolveType(attr.Type, sc.nsMap)
		} else if attr.SimpleType != nil {
			typeName = "string"
		} else {
			typeName = "string"
		}
		nsURI = sc.targetNS
	} else {
		return ""
	}

	fieldName := makeFieldName(name, true) // attribute fields always public

	var doc string
	if attr.Annotation != nil && len(attr.Annotation.Documentation) > 0 {
		d := strings.TrimSpace(attr.Annotation.Documentation[0])
		if d != "" {
			doc = formatDoc(d, indent)
		}
	}

	// For attribute fields, determine the Go type
	attrGoType := typeName
	if !isValueType(attrGoType) && !isDateTimeType(attrGoType) && attrGoType != "string" {
		// Custom type for attribute - use pointer
		attrGoType = "*" + strings.TrimPrefix(attrGoType, "*")
	}

	var xmlTagNS string
	if nsURI != "" {
		xmlTagNS = nsURI + " "
	}

	var result strings.Builder
	if doc != "" {
		result.WriteString(doc)
	}
	result.WriteString(fmt.Sprintf("%s%s %s `xml:\"%s%s,attr,omitempty\" json:\"%s,omitempty\"`",
		indent, fieldName, attrGoType, xmlTagNS, name, name))
	return result.String()
}

// resolveType resolves an XSD type to a Go type name
func (g *GoWSDL) resolveType(xsdType string, nsMap map[string]string) string {
	if xsdType == "" {
		return "string"
	}
	return resolveXSDType(xsdType, nsMap)
}

// getMessageType returns the Go type for a WSDL message reference
func (g *GoWSDL) getMessageType(messageName string) string {
	localName := getLocalName(messageName)
	for _, msg := range g.wsdl.Messages {
		if msg.Name == localName {
			if len(msg.Parts) == 0 {
				return "EmptyString"
			}
			for _, part := range msg.Parts {
				if part.Element != "" {
					return makePublicIdentifier(getLocalName(part.Element))
				}
				if part.Type != "" {
					return makePublicIdentifier(getLocalName(part.Type))
				}
			}
		}
	}
	return "EmptyString"
}

// getSoapAction gets the SOAP action for an operation
func (g *GoWSDL) getSoapAction(portTypeName, opName string) string {
	for _, binding := range g.wsdl.Bindings {
		bindingLocalType := getLocalName(binding.Type)
		if bindingLocalType == portTypeName {
			for _, op := range binding.Operations {
				if op.Name == opName {
					if op.SOAPOp != nil {
						return op.SOAPOp.SoapAction
					}
					if op.SOAP12Op != nil {
						return op.SOAP12Op.SoapAction
					}
				}
			}
		}
	}
	return ""
}

// genPortTypes generates the interface and implementations for all port types
func (g *GoWSDL) genPortTypes(ctx *generatorContext) string {
	var sb strings.Builder
	for _, pt := range g.wsdl.PortTypes {
		sb.WriteString(g.genPortType(pt, ctx))
	}
	return sb.String()
}

// genPortType generates interface and implementation for one port type
func (g *GoWSDL) genPortType(pt *PortType, ctx *generatorContext) string {
	var sb strings.Builder
	interfaceName := makeTypeName(pt.Name, true)
	structName := lowercaseFirst(interfaceName)

	// Collect operations and warn for messages with no parts
	var ops []*Operation
	for _, op := range pt.Operations {
		if op.Input != nil {
			localName := getLocalName(op.Input.Message)
			for _, msg := range g.wsdl.Messages {
				if msg.Name == localName && len(msg.Parts) == 0 {
					warn("%s message doesn't have any parts, ignoring message...", msg.Name)
					break
				}
			}
		}
		if op.Output != nil {
			localName := getLocalName(op.Output.Message)
			for _, msg := range g.wsdl.Messages {
				if msg.Name == localName && len(msg.Parts) == 0 {
					// Don't warn for output messages
					break
				}
			}
		}
		ops = append(ops, op)
	}

	if len(ops) == 0 {
		return ""
	}

	// Interface
	sb.WriteString(fmt.Sprintf("type %s interface {\n", interfaceName))
	for _, op := range ops {
		opName := makeOperationName(op.Name, g.makePublic)
		inputType, outputType := g.getOpTypes(op)

		if op.Documentation != "" {
			doc := strings.TrimSpace(op.Documentation)
			if doc != "" {
				sb.WriteString(fmt.Sprintf("\n\t/* %s */\n", doc))
			}
		} else {
			sb.WriteString("\n")
		}
		sb.WriteString(fmt.Sprintf("\t%s(request *%s) (*%s, error)\n\n", opName, inputType, outputType))
		ctxName := opName + "Context"
		sb.WriteString(fmt.Sprintf("\t%s(ctx context.Context, request *%s) (*%s, error)\n", ctxName, inputType, outputType))
	}
	sb.WriteString("}\n\n")

	// Struct
	sb.WriteString(fmt.Sprintf("type %s struct {\n\tclient *soap.Client\n}\n\n", structName))

	// Constructor
	sb.WriteString(fmt.Sprintf("func New%s(client *soap.Client) %s {\n", interfaceName, interfaceName))
	sb.WriteString(fmt.Sprintf("\treturn &%s{\n\t\tclient: client,\n\t}\n}\n\n", structName))

	// Method implementations
	for _, op := range ops {
		opName := makeOperationName(op.Name, g.makePublic)
		ctxName := opName + "Context"
		inputType, outputType := g.getOpTypes(op)
		soapAction := g.getSoapAction(pt.Name, op.Name)
		if soapAction == "" {
			soapAction = "''"
		}

		// Context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %s(ctx context.Context, request *%s) (*%s, error) {\n",
			structName, ctxName, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\tresponse := new(%s)\n", outputType))
		sb.WriteString(fmt.Sprintf("\terr := service.client.CallContext(ctx, %q, request, response)\n", soapAction))
		sb.WriteString("\tif err != nil {\n\t\treturn nil, err\n\t}\n\n")
		sb.WriteString("\treturn response, nil\n}\n\n")

		// Non-context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %s(request *%s) (*%s, error) {\n",
			structName, opName, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\treturn service.%s(\n\t\tcontext.Background(),\n\t\trequest,\n\t)\n}\n\n",
			ctxName))
	}

	return sb.String()
}

// getOpTypes returns the input and output type names for an operation
func (g *GoWSDL) getOpTypes(op *Operation) (string, string) {
	inputType := "EmptyString"
	outputType := "EmptyString"
	if op.Input != nil {
		inputType = g.getMessageType(op.Input.Message)
	}
	if op.Output != nil {
		outputType = g.getMessageType(op.Output.Message)
	}
	return inputType, outputType
}

// generateServerCode generates the server-side code
func (g *GoWSDL) generateServerCode() ([]byte, error) {
	var sb strings.Builder

	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString(fmt.Sprintf("package %s\n\n", g.pkg))
	sb.WriteString("import (\n\t\"encoding/xml\"\n\t\"errors\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"reflect\"\n\t\"strings\"\n)\n\n")

	// WSDL content
	sb.WriteString("var wsdl = `")
	sb.WriteString(g.wsdl.rawContent)
	sb.WriteString("`\n\n")

	sb.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	// Collect all server operations
	allOps := g.collectServerOps()

	// SOAPEnvelopeRequest
	sb.WriteString("type SOAPEnvelopeRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n")
	sb.WriteString("\tBody    SOAPBodyRequest\n")
	sb.WriteString("}\n\n")

	// SOAPBodyRequest
	sb.WriteString("type SOAPBodyRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n")
	sb.WriteString("\n")
	for _, op := range allOps {
		sb.WriteString(fmt.Sprintf("\t%s *%s `xml:,omitempty`\n", op.fieldName, op.inputType))
		sb.WriteString("\n")
	}
	sb.WriteString("}\n\n")

	// SOAPEnvelopeResponse
	sb.WriteString("type SOAPEnvelopeResponse struct {\n")
	sb.WriteString("\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n")
	sb.WriteString("\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n")
	sb.WriteString("\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n")
	sb.WriteString("\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n")
	sb.WriteString("\tBody SOAPBodyResponse\n")
	sb.WriteString("}\n\n")

	sb.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n")
	sb.WriteString("\treturn &SOAPEnvelopeResponse{\n")
	sb.WriteString("\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n")
	sb.WriteString("\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n")
	sb.WriteString("\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n")
	sb.WriteString("\t}\n}\n\n")

	// Fault
	sb.WriteString("type Fault struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n")
	sb.WriteString("\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n")
	sb.WriteString("\tCode   string `xml:\"faultcode,omitempty\"`\n")
	sb.WriteString("\tString string `xml:\"faultstring,omitempty\"`\n")
	sb.WriteString("\tActor  string `xml:\"faultactor,omitempty\"`\n")
	sb.WriteString("\tDetail string `xml:\"detail,omitempty\"`\n")
	sb.WriteString("}\n\n")

	// SOAPBodyResponse
	sb.WriteString("type SOAPBodyResponse struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"soap:Body\"`\n")
	sb.WriteString("\tFault   *Fault   `xml:\",omitempty\"`\n\n")
	for _, op := range allOps {
		sb.WriteString(fmt.Sprintf("\t%s *%s `xml:\",omitempty\"`\n\n", op.fieldName, op.outputType))
	}
	sb.WriteString("}\n\n")

	// Handler stubs
	for _, op := range allOps {
		sb.WriteString(fmt.Sprintf("func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n",
			op.fieldName, op.inputType, op.outputType))
		sb.WriteString("\treturn nil, WSDLUndefinedError\n}\n\n")
	}

	// Call function
	sb.WriteString(serverCallFunctionCode)

	// Endpoint
	sb.WriteString("func Endpoint(w http.ResponseWriter, r *http.Request) {\n")
	sb.WriteString("\trequest := SOAPEnvelopeRequest{}\n")
	sb.WriteString("\trequest.call(w, r)\n}\n")

	return []byte(sb.String()), nil
}

// serverOp represents an operation in the server
type serverOp struct {
	fieldName  string
	inputType  string
	outputType string
}

// collectServerOps collects all operations from all port types for the server
func (g *GoWSDL) collectServerOps() []serverOp {
	var ops []serverOp
	for _, pt := range g.wsdl.PortTypes {
		for _, op := range pt.Operations {
			inputType, outputType := g.getOpTypes(op)
			ops = append(ops, serverOp{
				fieldName:  inputType,
				inputType:  inputType,
				outputType: outputType,
			})
		}
	}
	return ops
}

const serverCallFunctionCode = `func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {
	w.Header().Add("Content-Type", "text/xml; charset=utf-8")
	val := reflect.ValueOf(&service.Body).Elem()
	n := val.NumField()
	var field reflect.Value
	var name string
	find := false

	if r.Method == http.MethodGet {
		w.Write([]byte(wsdl))
		return
	}

	resp := NewSOAPEnvelopResponse()
	defer func() {
		if r := recover(); r != nil {
			resp.Body.Fault = &Fault{}
			resp.Body.Fault.Space = "http://schemas.xmlsoap.org/soap/envelope/"
			resp.Body.Fault.Code = "soap:Server"
			resp.Body.Fault.Detail = fmt.Sprintf("%v", r)
			resp.Body.Fault.String = fmt.Sprintf("%v", r)
		}
		xml.NewEncoder(w).Encode(resp)
	}()

	header := r.Header.Get("Content-Type")
	if strings.Index(header, "application/soap+xml") >= 0 {
		panic("Could not find an appropriate Transport Binding to invoke.")
	}

	err := xml.NewDecoder(r.Body).Decode(service)
	if err != nil {
		panic(err)
	}

	for i := 0; i < n; i++ {
		field = val.Field(i)
		name = val.Type().Field(i).Name
		if field.Kind() != reflect.Ptr {
			continue
		}
		if field.IsNil() {
			continue
		}
		if field.IsValid() {
			find = true
			break
		}
	}

	if !find {
		panic(WSDLUndefinedError)
	} else {
		m := val.Addr().MethodByName(name + "Func")
		if !m.IsValid() {
			panic(WSDLUndefinedError)
		}

		vals := m.Call([]reflect.Value{field})
		if vals[1].IsNil() {
			reflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])
		} else {
			panic(vals[1].Interface())
		}
	}

}

