		return ""
	}
	lines := strings.Split(doc, "\\n")
	var result []string
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line != "" {
			result = append(result, indent+"// "+line)
		}
	}
	// Multi-line if original had newlines or we got multiple non-empty lines
	isMultiLine := hasNewline || len(result) > 1
	if isMultiLine {
