	if name == "" {
		return name
	}

	// Check if this should stay lowercase (type names)
	if goNamesKeepLower[name] {
		return name
	}

	// Special handling for "string" -> "Astring"
	if name == "string" {
		return "A" + name
	}

	// Replace dots with underscores
	s := strings.ReplaceAll(name, ".", "_")

	// Split by spaces, capitalize each word, join
	parts := strings.Fields(s)
